<script setup lang="ts">
import {computed,ref} from 'vue';import {usePlatform} from '../stores/platform';import {dataTypes} from '../domain';import ChartPanel from '../components/ChartPanel.vue';
import RemoteOperations from '../components/RemoteOperations.vue';
import {apiMode} from '../api/client';
const p=usePlatform(),range=ref('近一周'),metrics=ref<Record<string,string>>({});
const variants=[{title:'数据采集量',items:['当日采集','当日入库','统计入库','日均采集量'],unit:'条'},{title:'异常设备',items:['未登记设备','提供重复数据的设备','时间异常设备','模式异常'],unit:'台'},{title:'异常数据',items:['未登记数据数量','重复数据数量','时间异常数据数量','模式异常数据数量','格式异常数据数量'],unit:'条'},{title:'数据量异常设备',items:['在线无数据的设备量','数据异常增加的设备量','数据异常减少的设备量'],unit:'台'}];
const online=computed(()=>p.db.devices.filter(d=>d.status==='在线').length);
const modem=[['运行时间','72 小时'],['信号质量','良好'],['信号强度','-65 dBm'],['运营商类型','示例移动'],['网络注册数量','1'],['SIM 卡状态','正常'],['成功发送条数','128'],['发送量总数','130'],['SIM 卡账户余额','¥ 100.00']];
</script>
<template><RemoteOperations v-if="apiMode==='http'"/><template v-else><div class="operations-top"><section class="card"><h3>设备在线情况</h3><div class="totals"><div><p>设备总数</p><strong>{{p.db.devices.length}}</strong></div><div><p>在线设备</p><strong>{{online}}</strong></div><div><p>总在线率</p><strong>{{p.db.devices.length?Math.round(online/p.db.devices.length*100):0}}%</strong></div></div><div v-for="t in dataTypes" :key="t" class="stat">{{t}}<b>{{p.db.devices.filter(d=>d.type===t&&d.status==='在线').length}} / {{p.db.devices.filter(d=>d.type===t).length}} 台</b></div></section><section class="card"><h3>今日采集 / 累计采集</h3><div v-for="(t,i) in dataTypes" :key="t" class="stat">{{t}}<b>{{(i+1)*1200}} / {{(i+1)*120000}} 条</b></div><p class="muted">采集数量与入库数量分别统计</p></section><section class="card"><h3>短信猫状态</h3><dl class="modem"><template v-for="r in modem" :key="r[0]"><dt>{{r[0]}}</dt><dd>{{r[1]}}</dd></template></dl></section></div><section class="card section-head"><h3>数据统计图</h3><div class="spacer"/><el-select v-model="range" aria-label="统计时间范围"><el-option v-for="r in ['近一周','近一个月','近一个季度','近一年']" :key="r" :value="r"/></el-select></section><div v-for="(type,t) in dataTypes.slice(0,3)" :key="type" class="stack"><h2 class="type-heading">{{type}}数据</h2><div class="two-column"><ChartPanel v-for="(v,i) in variants" :key="v.title" :title="type+' · '+v.title+'统计图'" :labels="[metrics[type+i]||v.items[0]||'统计量']" :count="({'近一周':7,'近一个月':30,'近一个季度':90,'近一年':12} as Record<string,number>)[range]" :scale="(t+1)*(['近一周','近一个月','近一个季度','近一年'].indexOf(range)+1)*(v.items.indexOf(metrics[type+i]||v.items[0]||'')+1)" :exportable="i===1||i===3" :unit="v.unit"><el-select v-model="metrics[type+i]" :placeholder="v.items[0]" :aria-label="type+v.title+'指标'"><el-option v-for="m in v.items" :key="m" :value="m"/></el-select></ChartPanel></div></div></template></template>

